def solve(inp):
    R,C = len(inp), len(inp[0])
    g = [row[:] for row in inp]
    # find lines: full rows/cols of 2s
    lines_v = [c for c in range(C) if all(inp[r][c]==2 for r in range(R))]
    lines_h = [r for r in range(R) if all(inp[r][c]==2 for c in range(C))]
    blocks=[]
    for r in range(R):
        for c in range(C):
            if inp[r][c]==3:
                # center: cell with 2 inside 3x3
                if r>0 and r<R-1 and c>0 and c<C-1 and inp[r][c+1]==3 and inp[r+1][c]==3:
                    blocks.append((r+1,c))  # center at (r+1,c)? center is the 2 at (r+1? ) 
    # better: center = position of 2 that is surrounded by 3s
    blocks=[]
    for r in range(1,R-1):
        for c in range(1,C-1):
            if inp[r][c]==2 and all(inp[r+dr][c+dc]==3 for dr in(-1,0,1) for dc in(-1,0,1) if not(dr==0 and dc==0)):
                blocks.append((r,c))
    def run(ring_targets):
        g2=[row[:] for row in inp]
        for (br,bc) in blocks:
            if lines_v:  # vertical lines -> horizontal bar
                for c in range(C):
                    if g2[br][c]==0: g2[br][c]=1
            else:
                for r in range(R):
                    if g2[r][bc]==0: g2[r][bc]=1
        for (br,bc) in blocks:
            for L in ring_targets(bc):
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        r,cc=br+dr,L+dc
                        if 0<=r<R and 0<=cc<C:
                            if dr==0 and dc==0: g2[r][cc]=2
                            elif g2[r][cc]==0: g2[r][cc]=1
        return g2
    return lines_v, lines_h, blocks, run

